import { useEffect, useRef, useState } from "react";
import * as DialogPrimitive from "@radix-ui/react-dialog";
import { Dialog, DialogOverlay, DialogPortal } from "./ui/dialog";
import {
  USER_TYPE_VISITOR,
  checkUserByMobile,
  getUserProfile,
  isApiSuccess,
  persistSession,
  readApiBody,
  readApiError,
  readRequestError,
  saveVisitor,
  sendSms,
  sendWhatsApp
} from "../services/authApi";

const WELCOME_MESSAGE = [
  "Welcome to venturesdirectory.com, India's first real estate network and advertisement platform, ",
  "revolutionizing the property landscape by connecting buyers, sellers, agents, builders, and real estate business partners. ",
  "We provide a dynamic hub where property aspirations meet unparalleled opportunities. Join us to collectively fulfill everyone's dream of owning a property",
  ".\n\n Experience BuyRentsale.com through this Product Demo Video Link : https://www.youtube.com/watch?v=adEo19mS2c4\n\nMore details and step-by-step guide on venturesdirectory.com ",
  "PDF Link : https://api.buyrentsale.com/uploads/defaults/buyrentsale.pdf \n\nTeam,\nBuyrentsale.com\nMobile:9618641100\nEmail: support@buyrentsale.com"
].join("");

const otpSmsText = (otp) => `${otp} is your verification OTP for venturesdirectory.com. Please do not share this code with anyone. - AINEXT IT`;

const otpWhatsAppText = (otp) => `${otp} is your verification OTP for venturesdirectory.com. Please do not share this code with anyone. \n\nTeam,\nBuyrentsale.com\nMobile: 9618641100\nEmail: support@buyrentsale.com`;

const readUserId = (user) => user?.USERID || user?.UserID || 0;

function TermsAcceptance({ checked, onChange, onOpenTerms }) {
  return <div className="vd-login-terms">
    <input
      id="vd-accept-terms"
      type="checkbox"
      checked={checked}
      onChange={(event) => onChange(event.target.checked)}
      aria-label="I agree to the Terms and Conditions"
    />
    <a href="#terms" onClick={onOpenTerms}>Terms &amp; Conditions</a>
  </div>;
}

function TermsDialog({ open, onClose }) {
  const closeButtonRef = useRef(null);

  return <Dialog open={open} onOpenChange={(nextOpen) => { if (!nextOpen) onClose(); }}>
    <DialogPortal>
        <DialogOverlay className="vd-login-overlay" style={{ zIndex: 1700 }} />
      <DialogPrimitive.Content
        className="vd-nda-dialog"
        style={{ zIndex: 1710 }}
        aria-describedby="vd-nda-description"
        onOpenAutoFocus={(event) => {
          event.preventDefault();
          closeButtonRef.current?.focus();
        }}
      >
        <div className="vd-nda-header">
          <div>
            <DialogPrimitive.Title id="ndaTitle">VenturesDirectory.COM</DialogPrimitive.Title>
            <DialogPrimitive.Description id="vd-nda-description">Confidentiality and Non-Disclosure Agreement</DialogPrimitive.Description>
          </div>
          <button ref={closeButtonRef} type="button" className="vd-nda-close" aria-label="Close terms and conditions" onClick={onClose}>&times;</button>
        </div>
        <div className="vd-nda-body">
          <h3>CONFIDENTIALITY AND NON-DISCLOSURE AGREEMENT</h3>
          <p><strong>Between:</strong> Propify Realty Networks Pvt. Ltd. (“Propify”), operating venturesdirectory.com, and the individual or entity accepting this Agreement (“Recipient”).</p>
          <p><strong>Effective Date:</strong> Date and time of electronic acceptance.</p>
          <h4>1. Confidential Information</h4>
          <p>“Confidential Information” means non-public information disclosed, displayed, or made accessible through a property lead or related communication, including:</p>
          <ul>
            <li>Buyer requirements, seller requirements, investor enquiries, and acquisition mandates.</li>
            <li>Names, mobile numbers, contact details, and identities of buyers, sellers, landowners, investors, and intermediaries.</li>
            <li>Property addresses, survey numbers, exact locations, title particulars, asking prices, budgets, negotiation positions, and transaction status.</li>
            <li>Documents, communications, commercial proposals, referral arrangements, and information about the source or chain of introduction.</li>
            <li>Other information marked confidential or reasonably understood to be confidential in the circumstances.</li>
          </ul>
          <p>Confidential Information may belong to Propify, its clients, lead contributors, property owners, or other third parties.</p>
          <h4>2. Acknowledgement of Receipt</h4>
          <p>The Recipient acknowledges that the specific lead identified by its Lead ID or shared URL was accessed through VenturesDirectory.com after authentication and acceptance of the applicable terms.</p>
          <p>The Recipient agrees that Propify may rely on its access and acceptance records as evidence of that event, together with other relevant evidence, in resolving a dispute about the source or handling of the lead.</p>
          <p>This acknowledgement does not establish that Propify originally created every item of information or that the Recipient had no prior knowledge of the opportunity.</p>
          <h4>3. Obligations of the Recipient</h4>
          <p>The Recipient agrees to:</p>
          <ol type="a">
            <li>Keep Confidential Information secure and restrict access to persons who genuinely need it for an authorised transaction.</li>
            <li>Use the information only for the legitimate purpose for which the lead was shared.</li>
            <li>Not disclose, sell, publish, or commercially redistribute confidential contact details or lead information without appropriate authorisation.</li>
            <li>Not falsify, conceal, or deliberately misrepresent the source of the lead in order to evade an applicable contractual obligation.</li>
            <li>Not use confidential information to facilitate fraud, impersonation, harassment, unlawful solicitation, or other unlawful activity.</li>
            <li>Take reasonable precautions to prevent unauthorised copying, disclosure, or use.</li>
          </ol>
          <h4>4. Non-Circumvention and Commercial Protection</h4>
          <p>Where the lead has facilitated a connection or transaction subject to an applicable commission or referral arrangement, the Recipient shall not knowingly circumvent Propify or the relevant introducing party for the purpose of avoiding that agreed obligation.</p>
          <p>This restriction applies to deliberate evasion through nominees, associated entities, substitute intermediaries, or concealed transaction structures where the facts establish that the arrangement was used to defeat the applicable obligation.</p>
          <p>Any commission, referral fee, or revenue share remains subject to the applicable written or otherwise legally enforceable commercial arrangement. This NDA does not independently establish an unspecified fee or percentage.</p>
          <h4>5. Pre-Existing Knowledge and Exceptions</h4>
          <p>The Recipient is not prohibited from using information that the Recipient can demonstrate:</p>
          <ol type="a">
            <li>Was lawfully known before access to the relevant lead.</li>
            <li>Was obtained independently without using the Confidential Information.</li>
            <li>Became public through no breach of this Agreement.</li>
            <li>Was lawfully received from another source without a confidentiality restriction.</li>
            <li>Must be disclosed under applicable law or a lawful order, subject to any legally permissible notice to the affected party.</li>
          </ol>
          <p>Where the Recipient disputes the source of a lead, the parties shall consider contemporaneous records and other relevant evidence in good faith.</p>
          <h4>6. No Unauthorised Representation</h4>
          <p>The Recipient shall not represent that they are an employee, agent, exclusive representative, or authorised spokesperson of Propify unless separately authorised in writing.</p>
          <p>Nothing in this NDA transfers ownership of a third party's property, personal information, or other intellectual property to the Recipient or Propify.</p>
          <h4>7. Return, Deletion and Retention</h4>
          <p>Upon a reasonable written request, the Recipient shall cease unauthorised use and, where lawful and practicable, delete or return confidential copies that are no longer required for the permitted purpose.</p>
          <p>This obligation does not require deletion of records that must be retained by law, are reasonably required for a legitimate dispute or compliance purpose, or are preserved in routine secure backups, provided that they remain appropriately protected.</p>
          <h4>8. Duration</h4>
          <p>The obligations under this NDA apply from electronic acceptance and continue for twenty-four (24) months from the relevant lead-access date. Trade secrets and information otherwise entitled to longer protection remain protected for the period required by applicable law.</p>
          <h4>9. Breach and Legal Remedies</h4>
          <p>A party alleging breach may seek remedies available under applicable law, subject to proof of the breach and the relevant legal requirements. Depending on the circumstances, remedies may include recovery of proven losses, enforcement of an applicable payment obligation, or appropriate injunctive relief.</p>
          <p>No automatic penalty or unspecified commission is created by this clause.</p>
          <h4>10. Electronic Acceptance</h4>
          <p>The Recipient agrees that an affirmative acceptance recorded after OTP authentication may evidence agreement to this NDA, subject to applicable law.</p>
          <p>Propify may retain the applicable agreement version, Lead ID, authenticated mobile number, acceptance timestamp, and relevant audit records for lawful evidentiary and compliance purposes.</p>
          <h4>11. Governing Law and Disputes</h4>
          <p>This NDA is governed by the laws of India. The parties shall first attempt to resolve disputes through good-faith discussions. Unresolved disputes may be brought before competent courts at Hyderabad, Telangana, subject to applicable law and jurisdictional requirements.</p>
          <h4>12. Acceptance</h4>
          <p>By selecting “I Agree &amp; Continue,” the Recipient confirms that they have had an opportunity to review this NDA, understand its confidentiality and non-circumvention provisions, and voluntarily agree to be bound by its enforceable terms.</p>
          <div className="vd-nda-footer">
            <strong>Propify Realty Networks Pvt. Ltd.</strong><br />
            VenturesDirectory.com<br />
            Contact: 9618641100<br />
            Website: <a href="https://venturesdirectory.com/" target="_blank" rel="noopener noreferrer">https://venturesdirectory.com/</a>
          </div>
        </div>
        <div className="vd-nda-actions">
          <button type="button" onClick={onClose}>Close</button>
        </div>
      </DialogPrimitive.Content>
    </DialogPortal>
  </Dialog>;
}

function LoginModal({ open, onClose, onSuccess }) {
  const requestIdRef = useRef(0);
  const mobileInputRef = useRef(null);
  const otpInputRef = useRef(null);
  const [mobile, setMobile] = useState("");
  const [otp, setOtp] = useState("");
  const [generatedOtp, setGeneratedOtp] = useState("");
  const [termsAccepted, setTermsAccepted] = useState(false);
  const [otpSent, setOtpSent] = useState(false);
  const [otpInfo, setOtpInfo] = useState("");
  const [userExists, setUserExists] = useState(false);
  const [userData, setUserData] = useState([]);
  const [confirmOpen, setConfirmOpen] = useState(false);
  const [termsOpen, setTermsOpen] = useState(false);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");
  const [mobileError, setMobileError] = useState("");
  const [otpError, setOtpError] = useState("");

  const reset = () => {
    requestIdRef.current += 1;
    setMobile("");
    setOtp("");
    setGeneratedOtp("");
    setTermsAccepted(false);
    setOtpSent(false);
    setOtpInfo("");
    setUserExists(false);
    setUserData([]);
    setConfirmOpen(false);
    setTermsOpen(false);
    setLoading(false);
    setError("");
    setMobileError("");
    setOtpError("");
  };

  useEffect(() => {
    if (open) {
      reset();
    }
  }, [open]);

  useEffect(() => {
    if (otpSent) {
      otpInputRef.current?.focus();
    }
  }, [otpSent]);

  const closeModal = () => {
    reset();
    onClose();
  };

  const deliverOtp = async (mobileNumber, requestId) => {
    const nextOtp = String(Math.floor(100000 + Math.random() * 900000));
    setGeneratedOtp(nextOtp);
    setOtpSent(true);
    setOtp("");
    setOtpError("");
    setOtpInfo(`An OTP has been sent to ${mobileNumber}. Please check and enter it.`);
    setLoading(true);

    try {
      const results = await Promise.allSettled([
        sendSms(otpSmsText(nextOtp), mobileNumber),
        sendWhatsApp(mobileNumber, otpWhatsAppText(nextOtp))
      ]);
      if (requestId === requestIdRef.current && results.every((result) => result.status === "rejected")) {
        setError("Unable to validate Mobile number, Please try again later...!");
      }
    } catch {
      if (requestId === requestIdRef.current) {
        setError("Unable to validate Mobile number, Please try again later...!");
      }
    } finally {
      if (requestId === requestIdRef.current) {
        setLoading(false);
      }
    }
  };

  const finishLogin = async (users, requestId, isNewUser) => {
    const record = users?.[0];
    const userId = readUserId(record);
    if (!userId) {
      setError(isNewUser
        ? "USERID is missing in the response. Please try again."
        : "USERID is missing in existing data. Please try again.");
      return;
    }

    const authData = isNewUser
      ? {
        UserID: userId,
        UserName: userId,
        UserType: USER_TYPE_VISITOR,
        IsVisitor: record.IsVisitor || false,
        IsAgent: record.IsAgent || false,
        IsBuilder: record.IsBuilder || false
      }
      : {
        UserID: userId,
        UserName: userId,
        UserType: USER_TYPE_VISITOR,
        IsVisitor: record.IsVisitor || false,
        IsAgent: false,
        IsBuilder: false,
        IsProvider: false
      };

    const profileResponse = await getUserProfile(userId, USER_TYPE_VISITOR);
    if (requestId !== requestIdRef.current) {
      return;
    }

    const profile = readApiBody(profileResponse)?.[0];
    if (!isApiSuccess(profileResponse) || !profile) {
      setError("Unable to authenticate your details. Please try again later");
      return;
    }

    persistSession(authData, profile);
    onSuccess(profile);
  };

  const handleSendOtp = async (event) => {
    event.preventDefault();
    setError("");

    if (!/^\d{10}$/.test(mobile)) {
      setMobileError("Please enter a valid 10-digit number.");
      return;
    }

    const requestId = ++requestIdRef.current;
    setLoading(true);
    setUserExists(false);

    try {
      const response = await checkUserByMobile(mobile);
      if (requestId !== requestIdRef.current) {
        return;
      }

      if (!isApiSuccess(response)) {
        setError(readApiError(response, "Unable to validate the mobile number. Please try again."));
        setLoading(false);
        return;
      }

      const users = readApiBody(response);
      const list = Array.isArray(users) ? users : [];
      setUserData(list);

      if (list.length === 0) {
        setUserExists(false);
        setLoading(false);
        setConfirmOpen(true);
        return;
      }

      setUserExists(true);
      await deliverOtp(mobile, requestId);
    } catch (requestError) {
      if (requestId === requestIdRef.current) {
        setLoading(false);
        setError(readRequestError(requestError, "Something went wrong while validating the mobile number. Please try again later."));
      }
    }
  };

  const handleCreateAccount = async () => {
    setConfirmOpen(false);
    const requestId = ++requestIdRef.current;
    await deliverOtp(mobile, requestId);
  };

  const handleVerifyOtp = async (event) => {
    event.preventDefault();
    setError("");

    if (!/^\d{6}$/.test(otp)) {
      setOtpError("Please enter the OTP sent to your mobile.");
      return;
    }

    if (!termsAccepted) {
      setError("Please accept the Terms & Conditions.");
      return;
    }

    if (!generatedOtp || otp !== generatedOtp) {
      setError("Invalid OTP. Please try again.");
      return;
    }

    const requestId = ++requestIdRef.current;
    setLoading(true);

    try {
      if (!userExists) {
        const response = await saveVisitor(mobile);
        if (requestId !== requestIdRef.current) {
          return;
        }

        const createdUsers = readApiBody(response);
        const created = Array.isArray(createdUsers) ? createdUsers[0] : null;
        if (!isApiSuccess(response) || !created || readUserId(created) === 0) {
          setError("There was an error while saving your details. Please try again later.");
          setLoading(false);
          return;
        }

        sendWhatsApp(mobile, WELCOME_MESSAGE).catch(() => {});
        await finishLogin(createdUsers, requestId, true);
      } else {
        await finishLogin(userData, requestId, false);
      }
    } catch (requestError) {
      if (requestId === requestIdRef.current) {
        setError(readRequestError(requestError, "Unable to authenticate your details. Please try again later"));
      }
    } finally {
      if (requestId === requestIdRef.current) {
        setLoading(false);
      }
    }
  };

  const openTerms = (event) => {
    event.preventDefault();
    setTermsOpen(true);
  };

  return <>
    <Dialog open={open} onOpenChange={(nextOpen) => { if (!nextOpen && !termsOpen && !confirmOpen) closeModal(); }}>
      <DialogPortal>
        <DialogOverlay className="vd-login-overlay" style={{ zIndex: 1600 }} />
        <DialogPrimitive.Content
          className="vd-login-dialog"
          style={{ zIndex: 1610 }}
          aria-describedby="vd-login-description"
          onPointerDownOutside={(event) => {
            if (termsOpen || confirmOpen) event.preventDefault();
          }}
          onEscapeKeyDown={(event) => {
            if (termsOpen || confirmOpen) event.preventDefault();
          }}
          onOpenAutoFocus={(event) => {
            event.preventDefault();
            mobileInputRef.current?.focus();
          }}
        >
          <div className="vd-login-header">
            <DialogPrimitive.Title className="vd-login-title">Login with OTP</DialogPrimitive.Title>
            <button type="button" className="vd-login-x" onClick={closeModal} aria-label="Close">×</button>
          </div>

          <div className="vd-login-body">
            <DialogPrimitive.Description id="vd-login-description" className="vd-login-sr">
              Enter your WhatsApp mobile number to receive a one-time password.
            </DialogPrimitive.Description>

            {error ? <div className="vd-login-error" role="alert">{error}</div> : null}

            {!otpSent ? <form onSubmit={handleSendOtp} autoComplete="off">
              <div className="vd-login-field">
                <label htmlFor="vd-mobile-number">Enter Mobile No <span>(Whatsapp)</span></label>
                <input
                  ref={mobileInputRef}
                  id="vd-mobile-number"
                  className="form-control"
                  type="text"
                  inputMode="numeric"
                  maxLength={10}
                  placeholder="10-digit Mobile Number without +91"
                  value={mobile}
                  onChange={(event) => {
                    setMobile(event.target.value.replace(/\D/g, "").slice(0, 10));
                    setMobileError("");
                    setError("");
                  }}
                />
                {mobileError ? <div className="vd-login-field-error">{mobileError}</div> : null}
              </div>
              <TermsAcceptance checked={termsAccepted} onChange={setTermsAccepted} onOpenTerms={openTerms} />
              <button type="submit" className="btn btn-primary w-100" disabled={!/^\d{10}$/.test(mobile) || loading}>
                {loading ? "Please wait..." : "Send OTP"}
              </button>
            </form> : <form onSubmit={handleVerifyOtp} autoComplete="off">
              {otpInfo ? <div className="vd-login-otp-info" role="status">
                <span aria-hidden="true">✓</span>
                <p>{otpInfo}</p>
              </div> : null}
              <div className="vd-login-field">
                <label htmlFor="vd-otp-code">Enter OTP</label>
                <input
                  ref={otpInputRef}
                  id="vd-otp-code"
                  className="form-control"
                  type="text"
                  inputMode="numeric"
                  maxLength={6}
                  placeholder="Enter OTP"
                  value={otp}
                  onChange={(event) => {
                    setOtp(event.target.value.replace(/\D/g, "").slice(0, 6));
                    setOtpError("");
                    setError("");
                  }}
                />
                {otpError ? <div className="vd-login-field-error">{otpError}</div> : null}
              </div>
              <TermsAcceptance checked={termsAccepted} onChange={setTermsAccepted} onOpenTerms={openTerms} />
              <button type="submit" className="btn btn-primary w-100" disabled={!/^\d{6}$/.test(otp) || !termsAccepted || loading}>
                {loading ? "Please wait..." : "Verify OTP"}
              </button>
            </form>}
          </div>

          <div className="vd-login-footer">
            <button type="button" className="btn btn-primary" onClick={() => { closeModal(); window.location.assign("/"); }}>
              &lt;&lt; Home
            </button>
            <button type="button" className="btn btn-secondary" onClick={closeModal}>Close</button>
          </div>
        </DialogPrimitive.Content>
      </DialogPortal>
    </Dialog>

    <TermsDialog open={termsOpen} onClose={() => setTermsOpen(false)} />

    <Dialog open={confirmOpen} onOpenChange={(nextOpen) => { if (!nextOpen) setConfirmOpen(false); }}>
      <DialogPortal>
        <DialogOverlay className="vd-login-overlay" style={{ zIndex: 1800 }} />
        <DialogPrimitive.Content className="vd-login-confirm" style={{ zIndex: 1810 }} aria-describedby="vd-login-confirm-text">
          <DialogPrimitive.Title className="vd-login-sr">Create account</DialogPrimitive.Title>
          <p id="vd-login-confirm-text">The entered mobile number is not registered. Do you want to create new account ?</p>
          <div className="vd-login-confirm-actions">
            <button type="button" className="btn btn-danger" onClick={() => setConfirmOpen(false)}>No</button>
            <button type="button" className="btn btn-success" onClick={handleCreateAccount}>Yes</button>
          </div>
        </DialogPrimitive.Content>
      </DialogPortal>
    </Dialog>
  </>;
}

export default LoginModal;
